// Central de ajuda: perguntas comuns, cada uma com o atalho para resolver.
const HELP=[['ach',{v:'accounts',label:'help.openAccounts'}],['port',null],['notSteam',{v:'emulators',label:'help.openEmulators'}],['retroarch',{v:'emulators',label:'help.openEmulators'}],['pc',{act:'help-installed',label:'help.openInstalled'}],['stores',{v:'accounts',label:'help.openAccounts'}],['remove',null]];
function helpView(){const q=String(UI.helpQ||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const match=k=>!q||(T('help.q.'+k)+' '+T('help.a.'+k)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q);
 const items=HELP.filter(([k])=>match(k)).map(([k,go])=>`<details class="help-it" ${UI.helpOpen===k?'open':''} data-k="${k}"><summary>${esc(T('help.q.'+k))}</summary><div class="help-a"><p>${esc(T('help.a.'+k))}</p>${go?`<button class="btn btn-sm acc-cta" ${go.v?`data-act="go" data-v="${go.v}"`:`data-act="${go.act}"`}>${T(go.label)}</button>`:''}</div></details>`).join('');
 return `<main class="page help-page"><div class="page-h"><div><h1>${T('help.title')}</h1><p>${T('help.lead')}</p></div></div><input class="inp help-search" type="search" data-help-search placeholder="${T('help.search')}" value="${esc(UI.helpQ||'')}" aria-label="${T('help.search')}"><div class="help-list">${items||`<p class="muted">${T('help.none')}</p>`}</div><p class="help-foot">${T('help.more')} <button class="link-btn" data-act="bug-report">${T('bug.title')}</button></p></main>`;}
// Novidades: depois de atualizar, cartões curtos com o que mudou (uma vez por versão).
const NEWS={'3.2.0':[{k:'ports',icon:'M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0zM7 6H4v1a3 3 0 0 0 3 3M17 6h3v1a3 3 0 0 1-3 3'},{k:'covers',icon:'M4 5h16v14H4zM4 15l4-4 4 4 3-3 5 5M15 9h.01'},{k:'fixes2',icon:'M9 12l2 2 4-4M12 3l7 3v5c0 4.5-3 8.4-7 10-4-1.6-7-5.5-7-10V6z'}],'3.1.1':[{k:'epic',img:'/img/news-epic.jpg'},{k:'page',img:'/img/news-page.jpg'},{k:'light',icon:'M13 2 4 14h7l-1 8 9-12h-7z'},{k:'fixes',icon:'M9 12l2 2 4-4M12 3l7 3v5c0 4.5-3 8.4-7 10-4-1.6-7-5.5-7-10V6z'}]};
// Novidades: um slide por novidade (imagem, título e texto), com setas e pontos; uma vez por versão.
// Novidades: as da versão mais recente que tem novidades (uma correção pequena não repete a janela para quem já viu).
const verNum=v=>String(v||'').split('.').map(n=>parseInt(n,10)||0),verLess=(a,b)=>{const x=verNum(a),y=verNum(b);for(let i=0;i<3;i++)if((x[i]||0)!==(y[i]||0))return (x[i]||0)<(y[i]||0);return false;};
function newsKey(){const v=state.settings.version;return Object.keys(NEWS).filter(k=>!verLess(v,k)).sort((a,b)=>verLess(a,b)?-1:1).pop()||'';}
function newsDialog(){const k=newsKey(),list=NEWS[k];if(!list||(state.settings.seenVersion&&!verLess(state.settings.seenVersion,k)))return false;UI.newsIdx=0;renderNews();return true;}
function renderNews(){const v=state.settings.version,list=NEWS[newsKey()]||[],i=Math.max(0,Math.min(list.length-1,UI.newsIdx||0)),it=list[i],last=i===list.length-1;
 const media=it.img?`<img src="${it.img}" alt="">`:`<span class="news-big-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${it.icon}"/></svg></span>`;
 modal(`<div class="sheet news2" role="dialog" aria-modal="true" aria-labelledby="news-t"><button class="icon-btn close" data-act="news-close" aria-label="${T('ui.7b2006fd7af8')}">${I.x}</button><div class="news2-media ${it.img?'':'is-icon'}">${media}</div><div class="news2-body"><span class="ps-kick">${T('news.kick',{version:esc(v)})} · ${i+1}/${list.length}</span><h2 id="news-t">${T('news2.'+it.k+'.t')}</h2><p>${T('news2.'+it.k+'.d')}</p></div><div class="news2-foot"><span class="news2-dots">${list.map((_,j)=>`<button class="${j===i?'on':''}" data-act="news-go" data-i="${j}" aria-label="${j+1}"></button>`).join('')}</span><span class="news2-btns">${i?`<button class="btn btn-ghost" data-act="news-go" data-i="${i-1}">${T('ob.back')}</button>`:''}${last?`<button class="btn btn-primary" data-act="news-close">${T('news.ok')}</button>`:`<button class="btn btn-primary" data-act="news-go" data-i="${i+1}">${T('news.next')}</button>`}</span></div></div>`,'news');}
function render(){if(UI.languagePicker){renderLanguagePicker();return;}if(UI.ob){renderOnboarding();return;}const y=window.scrollY;const body=UI.view==='settings'?settingsView():UI.view==='emulators'?emulatorsView():UI.view==='accounts'?accountsView():UI.view==='steam'?steamView():UI.view==='owned'?ownedView():UI.view==='support'?supportView():UI.view==='help'?helpView():libraryView();$('#app').innerHTML=shell(body);for(const box of $$('.main-col .page-h .search'))box.remove();window.scrollTo(0,y);if(UI._focusQ){const input=$('#q')||$('#sq');input?.focus();input?.setSelectionRange(input.value.length,input.value.length);UI._focusQ=false;}onScroll();if(UI.view==='settings')injectorStatus();}
function onScroll(){$('#nav')?.classList.toggle('solid',window.scrollY>40||UI.view!=='library'||!!UI.q);}
let lastFocus;
function modal(html,key){achievementView?.destroy();achievementView=null;clearTimeout(achievementTimer);if(key!=='editor'&&E)E=null;if(!UI.modalKey)lastFocus=document.activeElement;$('#layer').innerHTML=`<div class="scrim" data-act="scrim">${html}</div>`;UI.modalKey=key;document.body.style.overflow='hidden';const sheet=$('#layer [role=dialog]');sheet?.setAttribute('tabindex','-1');sheet?.focus();}
function closeModal(force=false){if(working&&!force)return;achievementTicket++;achievementView?.destroy();achievementView=null;clearTimeout(achievementTimer);$('#layer').innerHTML='';UI.modalKey=null;document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function issues(list){return list?.length?`<details class="note warning"><summary>${list.length} ${T("ui.0afdd205f2ff")}</summary><ul>${list.map(e=>`<li>${esc(typeof e==='string'?TX(e):e.file+': '+TX(e.message))}</li>`).join('')}</ul></details>`:'';}
async function enrich(ids){const warnings=[];if(state.settings.preferences?.autoLookup===false)return warnings;for(let i=0;i<ids.length;i++){progress(T('operation.metadata',{current:i+1,total:ids.length}));try{const r=await api('recognize',{id:ids[i]});warnings.push(...(r.errors||[]),...(r.warnings||[]));}catch(e){warnings.push(e.message);}}return [...new Set(warnings)];}
// Capas e dados em segundo plano: o programa continua livre enquanto eles chegam.
const enrichQ=[];let enriching=false;UI.bg={search:'',art:''};
function bgChip(){const t=UI.bg.search||UI.bg.art;const c=$('#bgchip');if(c){c.hidden=!t;const s=c.querySelector('span');if(s)s.textContent=t;}}
function setBg(key,text){UI.bg[key]=text||'';bgChip();}
function enrichLater(ids){if(state.settings.preferences?.autoLookup===false||!ids?.length)return;for(const id of ids)if(!enrichQ.includes(id))enrichQ.push(id);if(!enriching)runEnrich();}
async function runEnrich(){enriching=true;let done=0;try{while(enrichQ.length){const id=enrichQ.shift();done++;setBg('art',T('bg.art',{current:done,total:done+enrichQ.length}));try{await api('recognize',{id});}catch{}if(done%4===0&&!dirty)await reload().catch(()=>{});}}finally{enriching=false;setBg('art','');if(!dirty)await reload().catch(()=>{});}}
// Depois de adicionar: artes, dados e envio à Steam acontecem em segundo plano.
const finishQ=[];let finishing=false;
function bgFinish(ids){if(!ids?.length)return;finishQ.push(...ids);if(!finishing)runFinish();}
async function runFinish(){finishing=true;try{while(finishQ.length){const ids=finishQ.splice(0,finishQ.length);setBg('art',T('bg.finish',{count:ids.length}));try{const r=await api('import-finish',{ids});if(r.merged?.length)toast(T('bg.merged',{title:r.merged.join(', ')}));if(r.steam?.message)toast(TX(r.steam.message),!!r.steam.error);}catch(e){toast(e.message,true);}if(!dirty)await reload().catch(()=>{});}}finally{finishing=false;setBg('art','');}}
// Busca sem travar: rápida primeiro (pastas dos emuladores, pastas comuns e lojas), completa no PC depois.
async function bgSearch(opts={}){if(UI.bg.search){toast(T('bg.busy'));return;}const sum={added:0,pending:0};
 const step=async(label,o)=>{setBg('search',label);try{const r=await importGames('discover',null,{...o,background:true,quiet:true});if(r){sum.added+=r.added.length;sum.pending=Math.max(sum.pending,r.pending);}}catch(e){toast(e.message,true);}};
 try{if(UI.discoverPromise){setBg('search',T('bg.quick'));await UI.discoverPromise.catch(()=>{});}if(!opts.deepOnly)await step(T('bg.quick'),{...opts,sweep:'home'});if(opts.deep!==false)await step(T('bg.deep'),{...opts,sweep:true,stores:false});
  // 2.2.9: também os jogos de PC instalados (pastas com prova de motor de jogo), não só ROMs e lojas. Ficam para revisão.
  if(opts.pc!==false){setBg('search',T('bg.pc'));try{const r=await api('installed-scan',{stores:false});portToast(r);const items=(r.items||[]).filter(x=>x.source!=='store');if(items.length){UI.pcPending=items;sum.pending+=items.length;}}catch{}}}
 finally{setBg('search','');}
 if(opts.quiet&&!sum.added&&!sum.pending)return;toast(sum.added||sum.pending?T('bg.done',{added:sum.added})+(sum.pending?' '+T('bg.review',{count:sum.pending}):''):T('discover.none'),!(sum.added||sum.pending));if(!dirty)await reload().catch(()=>{});}
