function draftFromForm(){const f=$('#config');if(!f)return draft;const b={...draft,preferences:{...draft.preferences}};for(const key of ['emulator','steamDir','scriptDir','account','raUser','sgdbKey','igdbId','igdbSecret','raKey','steamKey','language','achievementRoot','rpcs3Root','rpcs3User','vita3kRoot','shadps4Root','ps4TrophyKey','epicAccount','gogUser','profileServer','discordClientId']){if(f.elements[key])b[key]=f.elements[key].value;else delete b[key];}if(f.elements.raUseEmulatorAccounts)b.raUseEmulatorAccounts=f.elements.raUseEmulatorAccounts.checked;if(f.elements.injectSteam)b.injectSteam=f.elements.injectSteam.checked;if(f.elements.autoRestartSteam)b.autoRestartSteam=f.elements.autoRestartSteam.checked;if(f.elements.roots)b.roots=f.elements.roots.value.split('\n').map(s=>s.trim()).filter(Boolean);for(const key of ['autoLookup','closeSteam','scanOnStart','autoCollection','watchFolders','autoDiscover','autoSync','discordPresence','startWithWindows','showUninstalled','storeCollections','retroarchFirst','emuCollection'])if(f.elements[key])b.preferences[key]=f.elements[key].checked;if(f.elements.theme)b.preferences.theme=f.elements.theme.value;if(f.elements.epicInstaller)b.preferences.epicInstaller=f.elements.epicInstaller.value;return b;}
