 const line=!st.enabled?T('inj.off'):ok&&st.ngl==='error'?T('inj.nglError'):ok&&(st.ngl==='waiting'||st.ngl==='starting')?T('inj.nglWaiting'):ok?T('inj.on',{windows:st.ngl==='ready'?T('inj.ngl'):names}):!st.steamRunning?T('inj.waiting'):st.debugFlag===false?T('inj.needRestart'):T('inj.connecting');
