 if(st.state==='installing'||st.state==='paused'){const pct=Math.max(0,Math.min(100,Number(st.percent)||0)),mb=v=>v>=1024?(v/1024).toFixed(1)+' GB':Math.round(v)+' MB';
  const label=st.state==='paused'?T('sinst.paused'):st.phase==='tool'?T('sinst.tool'):st.phase==='preparing'?T('sinst.preparing'):st.phase==='finishing'?T('sinst.finishing'):T('sinst.downloading');
  return `${I.download||I.plus}<div class="inst-main"><b>${label}</b><div class="inst-bar"><span style="width:${pct}%"></span></div><small>${T('sinst.progress',{percent:pct.toFixed(pct<10?1:0)})}${st.totalMiB?' · '+mb(st.downloadedMiB||0)+' / '+mb(st.totalMiB):''}${st.eta&&st.phase==='downloading'?' · '+T('sinst.eta',{eta:st.eta}):''}</small></div>${st.state==='paused'?`<button class="btn btn-primary btn-sm" data-act="store-install" data-id="${g.id}">${T('sinst.resume')}</button>`:`<button class="btn btn-white btn-sm" data-act="store-install-pause" data-id="${g.id}">${T('sinst.pause')}</button>`}<button class="btn btn-ghost btn-sm" data-act="store-install-cancel" data-id="${g.id}">${T('sinst.cancel')}</button>`;}
 if(st.state==='external')return `${I.info||I.check}<span>${T(st.store==='xbox'?'sinst.externalXbox':'sinst.externalEpic')}</span><button class="btn btn-white btn-sm" data-act="store-install-cancel" data-id="${g.id}">${T('sinst.stopWatching')}</button>`;
