// Emuladores configurados, com as plataformas que cada um abre (nomes curtos).
function emulatorRows(){const st=state.settings,profiles=st.profiles||{},launchers={...(st.launchers||{})};if(st.emulator&&!launchers.psp?.exe)launchers.psp={exe:st.emulator};const short=name=>platformLabel(name).split(' · ')[0];return Object.entries(launchers).filter(([k,l])=>l?.exe&&profiles[k]?.files).map(([k,l])=>({profile:k,exe:l.exe,name:emuDisplay(k,l.exe),platforms:[...new Set((profiles[k].platforms||[]).map(short))].slice(0,6).join(' · ')||profiles[k].platform})).sort((a,b)=>a.name.localeCompare(b.name));}
function emuDisplay(profile,exe){const base=String(exe||'').split(/[\\/]/).pop().toLowerCase(),known={'epsxe.exe':'ePSXe','visualboyadvance-m.exe':'VBA-M','desmume.exe':'DeSmuME','desmume_x64.exe':'DeSmuME','rasnes9x.exe':'RASnes9x','rap64.exe':'RAP64','rmg.exe':"Rosalie's Mupen GUI",'simple64-gui.exe':'simple64','yuzu.exe':'yuzu','citron.exe':'Citron','eden.exe':'Eden','sudachi.exe':'Sudachi','citra-qt.exe':'Citra','lime3ds.exe':'Lime3DS','xenia_canary.exe':'Xenia Canary'};return known[base]||state.settings.profiles?.[profile]?.name||profile;}
function raStatusHTML(){const ra=state.settings.ra||{};const line=ra.source==='emulator'?T('ra.status.emulator',{user:esc(ra.user),emulator:esc(ra.emulator||'')}):ra.source==='taiga'?T('ra.status.taiga',{user:esc(ra.user)}):ra.source==='webapi'?T('ra.status.webapi',{user:esc(ra.user)}):T('ra.status.none');const others=(ra.emulatorAccounts||[]).filter(a=>a.user!==ra.user);return `<div class="ra-status ${ra.connected?'ok':''}"><span class="ok-dot">${ra.connected?I.check:''}</span><p>${line}</p></div>${others.length?`<p class="note">${T('ra.otherAccounts')} ${others.map(a=>esc(a.user+' ('+a.emulators.join(', ')+')')).join(' · ')}</p>`:''}<p class="note">${T('ra.hashNote')}</p>`;}
function raLoginDialog(){modal(`<div class="sheet dlg" role="dialog" aria-modal="true" aria-label="RetroAchievements"><button class="icon-btn close" data-act="close" aria-label="${T("ui.7b2006fd7af8")}">${I.x}</button><h2>RetroAchievements</h2><p>${T('ra.loginIntro')}</p><form id="ra-login-form" class="dlg-form"><label>${T('ra.username')}<input class="inp" name="user" autocomplete="username" required maxlength="32" value="${esc(state.settings.raUser||'')}"></label><label>${T('ra.password')}<input class="inp" name="password" type="password" autocomplete="current-password" required></label><p class="note">${T('ra.passwordNote')}</p><div class="dlg-foot"><button type="button" class="btn btn-ghost" data-act="close">${T("ui.c111e0ab9ddb")}</button><button class="btn btn-primary">${T('ra.loginButton')}</button></div></form></div>`,'ra-login');$('#ra-login-form').onsubmit=e=>{e.preventDefault();const f=e.target;task(async()=>{const r=await api('ra-login',{user:f.elements.user.value,password:f.elements.password.value});f.elements.password.value='';closeModal(true);await reload();toast(r.message);},T('ra.connecting'));};}
// Por que um jogo não pode ir para a Steam agora: mensagem clara com o motivo e o lugar para resolver.
function syncBlocker(games){const st=state.settings;if(!st.readiness.steam)return {text:T('sync.noSteam'),view:'settings'};if(!st.readiness.account)return {text:T('sync.noAccount'),view:'settings'};
 const g=games.find(g=>!g.demo&&!g.launchReady);if(!g)return null;const p=g.problems||[];
 if(p.includes('FILE_MISSING'))return {text:T('sync.noFile',{title:g.title}),open:()=>{}};
 if(p.includes('EMULATOR_MISSING')){const emu=st.profiles?.[g.profile]?.name||g.platformName||'';if(Array.isArray(st.retroarchPlatforms)&&g.platformName&&!st.retroarchPlatforms.includes(g.platformName))return {text:T('sync.noCore',{title:g.title,platform:platformLabel(g.platformName),emu}),open:()=>{closeModal?.(true);UI.view='emulators';render();}};return {text:T('sync.noEmu',{title:g.title,emu}),open:()=>{closeModal?.(true);UI.view='emulators';render();}};}
 if(p.includes('NEEDS_REVIEW'))return {text:T('sync.review',{title:g.title}),open:()=>{}};
 return {text:g.launchError&&g.launchError!=='FILE_MISSING'?T('sync.cantRunWhy',{title:g.title,reason:TX(g.launchError)}):T('sync.cantRun',{title:g.title}),open:()=>{}};}
function syncDialog(ids,remove=false){const games=ids.map(G).filter(Boolean);if(!games.length)return;if(!remove){const why=syncBlocker(games);if(why){toast(why.text,true);if(why.view){UI.view=why.view;render();}else if(why.open)why.open();return;}}modal(`<div class="sheet dlg" role="dialog" aria-modal="true" aria-label="${T("ui.28b543e157eb")}"><button class="icon-btn close" data-act="close" aria-label="${T("ui.7b2006fd7af8")}">${I.x}</button><h2>${remove?T("ui.d938ec6f7f43"):T("ui.28b543e157eb")}</h2><p>${games.length} ${T("ui.0ba8e53a0694")} ${esc(state.settings.accounts.find(a=>a.id===state.settings.account)?.name||state.settings.account)}.</p>${games.map(g=>`<div class="note"><b>${esc(g.title)}</b>${g.demo?("<p>"+T("ui.7bec668a83e8")+"</p>"):''}${!remove&&g.steamCandidates?.length&&!g.appId?`<label>${T("ui.31d1b7c2fabc")}<select class="inp" data-adopt="${g.id}"><option value="">${T("ui.b72c7af1bf03")}</option>${g.steamCandidates.map(c=>`<option value="${c.appId}">${esc(c.title)} · ${c.appId}</option>`).join('')}</select></label>`:''}</div>`).join('')}<p class="note">${remove?T("ui.9b07244f89f5"):T("ui.a81926e51839")}</p><label class="check-row"><input type="checkbox" id="sync-restart" ${state.settings.preferences?.closeSteam!==false?'checked':''}>${T("ui.87b61004a214")}</label>${state.settings.injectSteam===false?`<label class="check-row"><input type="checkbox" id="sync-integration" checked>${T("ui.d7b6a1fa9aca")}</label>`:''}<div class="dlg-foot"><button class="btn btn-ghost" data-act="close">${T("ui.c111e0ab9ddb")}</button><button id="sync-confirm" class="btn ${remove?'btn-danger':'btn-primary'}">${remove?T("ui.a497f5acf36a"):T("ui.ab4a343ad66e")}</button></div></div>`,'sync');$('#sync-confirm').onclick=()=>task(async()=>{const adopt={};$$('[data-adopt]').forEach(s=>{if(s.value)adopt[s.dataset.adopt]=s.value;});const result=await api('sync',{ids:games.map(g=>g.id),remove,restart:$('#sync-restart').checked,openSteam:$('#sync-restart').checked,installIntegration:($('#sync-integration')?.checked??false),adopt});closeModal(true);await reload();toast(result.message);(result.warnings||[]).forEach(w=>toast(w,true));},T("ui.7bac4e2357e7"));}
