const EVID={unity:'Unity',unreal:'Unreal',godot:'Godot',gamemaker:'GameMaker',renpy:"Ren'Py",rpgmaker:'RPG Maker',steamworks:'Steam',eos:'Epic Online',bink:'Bink',fmod:'FMOD'};
// Port para PC encontrado: entrou no lugar da versão do emulador do mesmo jogo.
function portToast(r){if(r?.adopted?.length){toast(T('port.adopted',{names:r.adopted.map(a=>a.title).join(', ')}));reload().catch(()=>{});}}
async function installedDialog(after){const r=await api('installed-scan',{});portToast(r);UI.inst={items:r.items||[],sel:new Set((r.items||[]).filter(x=>x.confidence==='high').map(x=>x.path)),after};renderInstalled();}
function renderInstalled(){const st=UI.inst,items=st.items;const row=x=>`<label class="inst-row"><input type="checkbox" data-inst="${esc(x.path)}" ${st.sel.has(x.path)?'checked':''}><span class="inst-ic emu-ic" style="--h:${hueOf(x.title)}"><i>${esc(x.title.replace(/[^A-Za-z0-9]/g,'').slice(0,2).toUpperCase()||'?')}</i><img src="/exe-icon?p=${encodeURIComponent(x.path)}" alt=""></span><span class="inst-t"><b>${esc(x.title)}</b><small title="${esc(x.path)}">${esc(x.root)}</small></span><span class="inst-tags">${x.storeName&&x.store!=='windows'?`<em>${esc(x.storeName)}</em>`:''}${(x.evidence||[]).slice(0,2).map(e=>`<em>${esc(EVID[e]||e)}</em>`).join('')}</span></label>`;
 modal(`<div class="sheet dlg inst" role="dialog" aria-modal="true" aria-labelledby="inst-t"><button class="icon-btn close" data-act="close" aria-label="${T("ui.7b2006fd7af8")}">${I.x}</button><h2 id="inst-t">${T('inst.title')}</h2><p class="sa-lead">${items.length?T('inst.lead'):T('inst.none')} ${T('inst.inCollection')}</p>
 ${items.length?`<div class="inst-selbar"><label class="check-row"><input type="checkbox" data-inst-all ${items.every(x=>st.sel.has(x.path))?'checked':''}><span>${T("ui.a54c2fdb6516")}</span></label><span>${T('inst.selected',{count:st.sel.size})}</span></div><div class="inst-list">${items.map(row).join('')}</div>`:''}
 <div class="dlg-foot">${items.length?`<button class="btn btn-ghost" data-act="close">${T('account.later')}</button><button class="btn btn-primary" data-act="inst-add" ${st.sel.size?'':'disabled'}>${I.plus}${T('inst.add',{count:st.sel.size})}</button>`:`<button class="btn btn-primary" data-act="close">OK</button>`}</div></div>`,'installed');}
async function importInstalled(list){const res=await api('scan',{paths:list.map(x=>x.path),preview:true});const byPath=new Map(list.map(x=>[x.path.toLowerCase(),x]));let resolved=[];for(let i=0;i<res.items.length;i+=25){const r=await api('import-resolve',{scanId:res.scanId,paths:res.items.slice(i,i+25).map(g=>g.path)});resolved.push(...r.items);}
 const items=resolved.map(g=>{const x=byPath.get(g.path.toLowerCase());return x?{...g,title:x.title,gameRoot:x.root}:g;}),added=[];
 for(let i=0;i<items.length;i+=200){const r=await api('import-confirm',{scanId:res.scanId,deferred:true,items:items.slice(i,i+200).map(importItem)});added.push(...r.addedIds);}
 bgFinish(added);await reload();return added.length+(res.existing||[]).length;}

