async function backgroundDiscover(){if(UI.discovering)return;const last=Date.parse(state.settings.discoveredAt||'')||0;if(last&&Date.now()-last<12*3600000)return;UI.discovering=true;render();const run=importGames('discover',null,{background:true,sweep:!last}).catch(()=>{});UI.discoverPromise=run;try{await run;}finally{UI.discovering=false;UI.discoverPromise=null;if(!working){const o=$('#operation');if(o)o.hidden=true;}render();}}
