function watchDiscover(){let on=true;const tick=async()=>{if(!on)return;try{const p=await api('discover-progress');if(on&&p.phase&&Date.now()-p.at<120000)progress(T('disc.p.'+p.phase,{done:p.done,total:p.total}));}catch{}if(on)setTimeout(tick,900);};setTimeout(tick,400);return ()=>{on=false;};}
