 if(kind==='discover'){if(!(result.items||[]).length){if(!bg)toast((result.existing||[]).length?T('discover.nothingNew',{count:result.existing.length}):T('discover.none'),!(result.existing||[]).length);return {added:[],pending:0,existing:(result.existing||[]).length};}if(!bg)toast(T('discover.found',{count:result.items.length,folders:(result.folders||[]).length}));}if(kind==='stores'&&!(result.items||[]).length&&!(result.existing||[]).length){toast(T('stores.none'),true);return;}if(kind==='stores'&&result.stores?.length)toast(T('stores.found',{count:(result.items||[]).length,stores:result.stores.join(', ')}));
 IM={scanId:result.scanId,items:result.items||[],existing:result.existing||[],errors:result.errors||[],roots:kind==='folder'?paths:[],queue:[],index:0};
